1	import 'dart:async';
2	
3	import 'package:flutter/material.dart';
4	import 'package:fpdart/fpdart.dart' hide State;
5	import 'package:go_router/go_router.dart';
6	
7	import 'core/di/injection_container.dart';
8	import 'core/failure/failure.dart';
9	import 'core/navigation/app_router.dart';
10	import 'core/navigation/expiry_overlay_host.dart';
11	import 'features/account/domain/repositories/account_settings_repository.dart';
12	import 'features/auth/domain/repositories/session_repository.dart';
13	import 'features/vault/domain/repositories/vault_repository.dart';
14	
15	Future<void> main() async {
16	  WidgetsFlutterBinding.ensureInitialized();
17	  try {
18	    await setupCoreDependencies();
19	  } catch (error) {
20	    debugPrint(
21	      'Cerne failed to start: could not load .env ($error). Copy '
22	      '.env.example to .env and fill in FUNCTIONS_BASE_URL + '
23	      'SUPABASE_ANON_KEY before running the app.',
24	    );
25	    rethrow;
26	  }
27	  // Review finding: `app_router.dart`'s `_redirect` composes the vault
28	  // gate (AD-14) strictly first, synchronously, ahead of everything else —
29	  // it routes to `/vault` on the very first redirect evaluation, before
30	  // `CerneApp`'s own fire-and-forget boot fetch below could ever resolve.
31	  // `/vault`'s builder reads `currentBiometricEnabled` synchronously at
32	  // that moment, so without this awaited (bounded) fetch here, every cold
33	  // start reads the untouched default (`true`) regardless of what the user
34	  // actually set — not the "one-time, benign gap on a slow-network cold
35	  // boot" it looked like. Bounded so a hung network call can't delay app
36	  // launch indefinitely; on timeout/failure, `currentBiometricEnabled` is
37	  // simply left at its documented default, same outcome as before this
38	  // fix.
39	  await sl<AccountSettingsRepository>()
40	      .fetchBiometricEnabled()
41	      .timeout(const Duration(seconds: 2), onTimeout: () => right(unit))
42	      .catchError(_asUnchangedPreference);
43	  runApp(const CerneApp());
44	}
45	
46	// `catchError`'s handler must still complete the Future with a value of
47	// its declared type (`Either<Failure, Unit>`) — a `void`-returning handler
48	// would try to complete it with `null`, which isn't assignable to that
49	// non-nullable type and would itself throw. Top-level (not a
50	// `_CerneAppState` method) so both `main()`'s own awaited fetch above and
51	// `CerneApp.initState`'s fire-and-forget one below can share it.
52	Either<Failure, Unit> _asUnchangedPreference(
53	  Object error,
54	  StackTrace stackTrace,
55	) {
56	  debugPrint('Cerne: fetchBiometricEnabled() threw unexpectedly ($error)');
57	  return left(Failure.malformedResponse(message: error.toString()));
58	}
59	
60	/// Root widget. Portrait-only, light-mode-only, fixed 390x844 frame — no
61	/// breakpoint, landscape or dark-mode path anywhere in the app (per the
62	/// epic's UX constraints; the portrait lock itself lives in
63	/// `ios/Runner/Info.plist`, Story 1.6).
64	///
65	/// Story 1.6 scope: the ad-hoc `StreamBuilder`/`Navigator.push` shell
66	/// Stories 1.3-1.5 built this on top of is replaced by the one real
67	/// `go_router` (`core/navigation/app_router.dart`) plus its
68	/// `ExpiryOverlayHost` wrapper — [restoreSession] still fires once at boot
69	/// here (unchanged from Story 1.4), but every screen transition and the
70	/// expiry overlay's own "Entrar novamente" now go through that router
71	/// instead of an imperative `Navigator`.
72	class CerneApp extends StatefulWidget {
73	  const CerneApp({super.key});
74	
75	  @override
76	  State<CerneApp> createState() => _CerneAppState();
77	}
78	
79	class _CerneAppState extends State<CerneApp> {
80	  late final SessionRepository _sessionRepository;
81	  late final VaultRepository _vaultRepository;
82	  late final AccountSettingsRepository _accountSettingsRepository;
83	  late final GoRouter _router;
84	
85	  // Created here (not left for `GoRouter` to generate internally) and
86	  // passed to both `buildAppRouter` and `ExpiryOverlayHost` below, so the
87	  // latter can reach the Navigator's own `BuildContext` through this
88	  // public, documented key instead of reaching into `GoRouter`'s internal
89	  // `routerDelegate`.
90	  final GlobalKey<NavigatorState> _navigatorKey = GlobalKey<NavigatorState>(
91	    debugLabel: 'root',
92	  );
93	
94	  @override
95	  void initState() {
96	    super.initState();
97	    _sessionRepository = sl<SessionRepository>();
98	    _vaultRepository = sl<VaultRepository>();
99	    _accountSettingsRepository = sl<AccountSettingsRepository>();
100	    _router = buildAppRouter(
101	      vaultRepository: _vaultRepository,
102	      sessionRepository: _sessionRepository,
103	      accountSettingsRepository: _accountSettingsRepository,
104	      navigatorKey: _navigatorKey,
105	    );
106	    // Fire-and-forget: the outcome reaches the UI through
107	    // `SessionRepository.currentStatus`/`statusStream` (which the router's
108	    // `redirect`/`refreshListenable` already watch), not through this
109	    // call's return value. `restoreSession()` already maps every internal
110	    // failure to `Left`/an `unauthenticated` emission and never throws.
111	    // This `catchError` is NOT a UI recovery path — its handler's return
112	    // value is discarded by `unawaited` and never reaches `statusStream`.
113	    // It exists purely so a future regression that broke the "never
114	    // throws" contract above would surface as a logged message instead of
115	    // an unhandled zone exception.
116	    unawaited(
117	      _sessionRepository.restoreSession().catchError(_asUnauthenticated),
118	    );
119	    // Story 2.4 — boot-time read of `biometricEnabled`, same
120	    // fire-and-forget rationale as `restoreSession()` above: the outcome
121	    // reaches `VaultLockScreen` through `AccountSettingsRepository.
122	    // currentBiometricEnabled`/`biometricEnabledStream` (which the router's
123	    // `refreshListenable` already watches), never through this call's
124	    // return value, and a failure leaves `currentBiometricEnabled`
125	    // unchanged (I/O matrix) rather than surfacing anywhere.
126	    unawaited(
127	      _accountSettingsRepository.fetchBiometricEnabled().catchError(
128	        _asUnchangedPreference,
129	      ),
130	    );
131	  }
132	
133	  @override
134	  void dispose() {
135	    _router.dispose();
136	    super.dispose();
137	  }
138	
139	  // `catchError`'s handler must still complete the Future with a value of
140	  // its declared type (`Either<Failure, Unit>`) — a `void`-returning
141	  // handler would try to complete it with `null`, which isn't assignable
142	  // to that non-nullable type and would itself throw.
143	  static Either<Failure, Unit> _asUnauthenticated(
144	    Object error,
145	    StackTrace stackTrace,
146	  ) {
147	    debugPrint('CerneApp: restoreSession() threw unexpectedly ($error)');
148	    return left(Failure.malformedResponse(message: error.toString()));
149	  }
150	
151	  @override
152	  Widget build(BuildContext context) {
153	    return MaterialApp.router(
154	      debugShowCheckedModeBanner: false,
155	      routerConfig: _router,
156	      builder: (context, child) => ExpiryOverlayHost(
157	        sessionRepository: _sessionRepository,
158	        router: _router,
159	        navigatorKey: _navigatorKey,
160	        child: child!,
161	      ),
162	    );
163	  }
164	}
